sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader backdrop;
uniform float4 screen;
uniform float2 center;
uniform float angle;
uniform float reach;
uniform float angleChannel;
uniform float distanceChannel;
uniform float edges;
uniform float fromCenter;
uniform float invert;
float2 edged(float2 p, float mode) {
    float2 q = (p - screen.xy) / screen.zw;
    if (mode < 0.5) q = clamp(q, 0.5 / screen.zw, 1.0 - 0.5 / screen.zw);
    else if (mode < 1.5) q = 1.0 - abs(1.0 - mod(q, 2.0));
    else if (mode > 2.5) q = fract(q);
    return screen.xy + q * screen.zw;
}
float pick(half4 c, float ch) {
    float3 u = c.a > 0.0 ? float3(c.rgb) / float(c.a) : float3(0.0);
    if (ch < 0.5) return u.r;
    if (ch < 1.5) return u.g;
    if (ch < 2.5) return u.b;
    if (ch < 3.5) return dot(u, float3(0.2126, 0.7152, 0.0722));
    return float(c.a);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return half4(0.0);
    float ma = pick(src, angleChannel);
    float mr = pick(src, distanceChannel);
    if (invert > 0.5) {
        ma = 1.0 - ma;
        mr = 1.0 - mr;
    }
    if (fromCenter > 0.5) {
        ma = ma * 2.0 - 1.0;
        mr = mr * 2.0 - 1.0;
    }
    float2 c = size * 0.5 + center;
    float2 d = coord - c;
    float r = length(d) - reach * mr;
    float a = atan(d.y, d.x) - radians(angle) * ma;
    return backdrop.eval(edged(c + r * float2(cos(a), sin(a)), edges)) * src.a;
}
